var building = new Building(1, "Engineering Building", "Blue", 10.5f, 20.0f, 15.0f, 100.0f, 0.0f, 200.0f);
Assert.That(building.Name, Is.EqualTo("Engineering Building"));
Assert.That(building.Color, Is.EqualTo("Blue"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(1, "", "Blue", 10.5f, 20.0f, 15.0f, 100.0f, 0.0f, 200.0f));
Assert.That(ex.ParamName, Is.EqualTo("name"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(1, "Engineering Building", "", 10.5f, 20.0f, 15.0f, 100.0f, 0.0f, 200.0f));
Assert.That(ex.ParamName, Is.EqualTo("color"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(1, "Engineering Building", "Blue", 0f, 20.0f, 15.0f, 100.0f, 0.0f, 200.0f));
Assert.That(ex.ParamName, Is.EqualTo("height"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(1, "Engineering Building", "Blue", 10.5f, -5.0f, 15.0f, 100.0f, 0.0f, 200.0f));
Assert.That(ex.ParamName, Is.EqualTo("length"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(1, "Engineering Building", "Blue", 10.5f, 20.0f, 0f, 100.0f, 0.0f, 200.0f));
Assert.That(ex.ParamName, Is.EqualTo("width"));

var building = new Building(1, "Old Name", "Red", 10.0f, 20.0f, 15.0f, 0f, 0f, 0f);
building.Update("Updated Building", "Blue", 12.5f, 25.0f, 18.0f, 100.0f, 5.0f, 200.0f);
Assert.That(building.Name, Is.EqualTo("Updated Building"));
Assert.That(building.Color, Is.EqualTo("Blue"));

